from functools import lru_cache
class Solution:
    def isScramble(self, s1, s2):
        n=len(s1)
        if n!=len(s2): return False
        @lru_cache(None)
        def dp(i,j,L):
            if s1[i:i+L]==s2[j:j+L]: return True
            if sorted(s1[i:i+L])!=sorted(s2[j:j+L]): return False
            for k in range(1,L):
                if dp(i,j,k) and dp(i+k,j+k,L-k): return True
                if dp(i,j+L-k,k) and dp(i+k,j,L-k): return True
            return False
        return dp(0,0,n)

