using namespace std;
class Solution {
public:
    bool isScramble(string s1, string s2) {
        int n=s1.size(); if(n!= (int)s2.size()) return false;
        vector<vector<vector<int>>> memo(n+1, vector<vector<int>>(n, vector<int>(n,-1)));
        function<bool(int,int,int)> dfs = [&](int i,int j,int L)->bool {
