import java.io.*;
import java.util.*;
class Solution {
    public boolean isScramble(String s1,String s2){
        int n=s1.length(); if(n!=s2.length()) return false;
        byte[][][] memo=new byte[n+1][n][n];
        for(byte[][] a:memo) for(byte[] b:a) Arrays.fill(b,(byte)-1);
        return dfs(s1,s2,0,0,n,memo);
    }
    private boolean dfs(String a,String b,int i,int j,int len,byte[][][] m){
        if(m[len][i][j]!=-1)return m[len][i][j]==1;
        if(a.regionMatches(i,b,j,len)){m[len][i][j]=1;return true;}
        int[] cnt=new int[26];for(int k=0;k<len;k++){cnt[a.charAt(i+k)-'a']++;cnt[b.charAt(j+k)-'a']--;}
        for(int x:cnt)if(x!=0){m[len][i][j]=0;return false;}
        for(int k=1;k<len;k++){
            if(dfs(a,b,i,j,k,m)&&dfs(a,b,i+k,j+k,len-k,m)){m[len][i][j]=1;return true;}
            if(dfs(a,b,i,j+len-k,k,m)&&dfs(a,b,i+k,j,len-k,m)){m[len][i][j]=1;return true;}
        }
        m[len][i][j]=0;return false;
    }
}
