import sys, json
from functools import lru_cache
class Solution:
    def isScramble(self, s1: str, s2: str) -> bool:
        n=len(s1)
        if n != len(s2): return False
        @lru_cache(None)
        def dfs(i,j,L):
            if s1[i:i+L] == s2[j:j+L]: return True
            cnt=[0]*26
            for k in range(L):
                cnt[ord(s1[i+k])-97]+=1; cnt[ord(s2[j+k])-97]-=1
            if any(cnt): return False
            for k in range(1,L):
                if dfs(i,j,k) and dfs(i+k,j+k,L-k): return True
                if dfs(i,j+L-k,k) and dfs(i+k,j,L-k): return True
            return False
        return dfs(0,0,n)
if __name__ == '__main__':
    args=json.loads(sys.stdin.readline()); print(json.dumps(Solution().isScramble(args[0],args[1])))

